addpath('functions');

files = { ...
    'gdfs/ah7.20170613.161402.offline.mi.mi_bhbf.gdf', ...
    'gdfs/ah7.20170613.162331.offline.mi.mi_bhbf.gdf', ...
    'gdfs/ah7.20170613.162934.offline.mi.mi_bhbf.gdf'};

[s, h, sizes] = loadRuns(files);
SampleRate = h.SampleRate;

% sample rate = 512 Hz
% 17 channels
% sizes 172032, 162816, 165888
%%
lbl = labelEvents(h, sizes);

assert(all(structfun(@numel, lbl) == size(s, 1)));
% cues: 771 both feet, 773 both hands
%%
chNames = {'C3', 'Cz', 'C4'};
channels = channelIndex(chNames); % [7 9 11]

muButter = [8 13];
betaButter = [13 30];

sc = s(:, channels);

[sfiltmu, bmu, amu] = bandpassRuns(sc, lbl.Rk, muButter, 3, SampleRate);
[sfiltbe, bbe, abe] = bandpassRuns(sc, lbl.Rk, betaButter, 3, SampleRate);
%%
% filterAnalyzer(bmu, amu, 'SampleRates', SampleRate);
%%
% filterAnalyzer(bbe, abe, 'SampleRates', SampleRate);
%%
% square -> 1 s moving average (filter) -> ln, separately for each run.
% The first 1 s of each run is an initialization transient.
lsf_mu = logBandPower(sfiltmu, lbl.Rk, SampleRate, 1);
lsf_be = logBandPower(sfiltbe, lbl.Rk, SampleRate, 1);
%%
[trials, Ck, RunTrial, info] = extractTrials({sc, sfiltmu, sfiltbe, lsf_mu, lsf_be}, lbl, ...
    StartFrom="fixation", MaxLengthDiff=5);
[tRaw, tMu, tBe, tLmu, tLbe] = trials{:};

fprintf('Trials: %d, length %d..%d -> %d samples\n', numel(Ck), info.minLength, info.maxLength, size(tRaw, 1)); %[output:0ada0613]
%%
j = 1; % trial to inspect
t = (0:size(tRaw, 1)-1) ./ SampleRate; % time from fixation onset

stages = {tRaw, tMu, tBe, tLmu, tLbe};
stageNames = {'Raw', 'Mu [8-13] Hz', 'Beta [13-30] Hz', 'ln(P) mu', 'ln(P) beta'};
stageUnits = {'[uV]', '[uV]', '[uV]', 'ln(uV^2)', 'ln(uV^2)'};

figure('Position', [100 100 1200 1000]); %[output:85c00256]
ax = gobjects(numel(stages), numel(channels));
for k = 1:numel(stages)
    for c = 1:numel(channels)
        ax(k, c) = subplot(numel(stages), numel(channels), (k - 1) * numel(channels) + c); %[output:85c00256]
        plot(ax(k, c), t, stages{k}(:, c, j));
        markTrialEvents(ax(k, c), info.cueOnset(j), info.feedbackOnset(j), SampleRate, false);
        title(ax(k, c), sprintf('%s - %s', stageNames{k}, chNames{c}));
        ylabel(ax(k, c), stageUnits{k});
        % xlim(ax(k, c), [0, t(end)]);
    end
    linkaxes(ax(k, :), 'y');
end
for c = 1:numel(channels)
    xlabel(ax(end, c), 'time from fixation [s]'); %[output:85c00256]
end
sgtitle(sprintf('Trial #%d (run %d, cue %d)', j, RunTrial(j), Ck(j))); %[output:85c00256]
%%
fprintf('Cue onset: %.3f..%.3f s, feedback onset: %.3f..%.3f s from fixation\n', ... %[output:group:9c11cc4e] %[output:20d4d1dd]
    min(info.cueOnset) / SampleRate, max(info.cueOnset) / SampleRate, ... %[output:20d4d1dd]
    min(info.feedbackOnset) / SampleRate, max(info.feedbackOnset) / SampleRate); %[output:group:9c11cc4e] %[output:20d4d1dd]

cues = [771 773];
bands = {tLmu, tLbe};
bandNames = {'mu', 'beta'};

figure('Position', [100 100 1200 700]); %[output:59a2831a]
ax = gobjects(numel(bands), numel(channels));
for b = 1:numel(bands) %[output:group:0336505e]
    [avg, counts] = cueAverage(bands{b}, Ck, cues);
    for c = 1:numel(channels)
        ax(b, c) = subplot(numel(bands), numel(channels), (b - 1) * numel(channels) + c); %[output:59a2831a]
        hold(ax(b, c), 'on');
        for k = 1:numel(cues)
            plot(ax(b, c), t, avg(:, c, k), 'DisplayName', sprintf('Cue %d (%d trials)', cues(k), counts(k)));
        end
        markTrialEvents(ax(b, c), info.cueOnset, info.feedbackOnset, SampleRate, true);
        hold(ax(b, c), 'off');
        title(ax(b, c), sprintf('%s - %s', bandNames{b}, chNames{c}));
        xlabel(ax(b, c), 'time from fixation [s]');
        ylabel(ax(b, c), 'ln(P) [ln(uV^2)]');
        legend(ax(b, c), 'show', 'Location', 'best');
        xlim(ax(b, c), [0, t(end)]);
    end
    linkaxes(ax(b, :), 'y');
end %[output:group:0336505e]

